UPDATE dd_classes SET cla_nom = 'Archer sylvain', cla_abreviation = 'ArS', cla_clt_id = 2, cla_dV = 8, cla_alignement = '', cla_car_id = 0, cla_mag_id = 0, cla_profil_incantation = 0, cla_renouvellement = 0, cla_sort_connu = 0, cla_sort_compris = 0, cla_sort_prepare = 0, cla_domaine_divin = 0, cla_niveauMax = 10, cla_pointsCompetences = 4, cla_po_niveau1 = 0, cla_conditions = '', cla_armes = '<p>L&#39;archer sylvain n&#39;est form&eacute; au maniement d&#39;aucune arme, pas plus qu&#39;au port de l&#39;armure. Tous les pouvoirs relatifs aux armes de cette classe de prestige s&#39;appliquent uniquement aux armes &agrave; projectiles &agrave; distance que le personnage sait manier.</p>\r\n', cla_armures = NULL, cla_outils = NULL, cla_sauvegardes = NULL, cla_equipement = NULL, cla_competences = NULL, cla_sorts = NULL, cla_description = '<p>Une fl&egrave;che vole depuis le sommet d&#39;une montagne et frappe par surprise le destrier d&#39;un paladin. Ce dernier ne cache pas sa surprise lorsque son compagnon s&#39;&eacute;croule au sol. Cet infortun&eacute; chevalier vient de p&eacute;n&eacute;trer sur le territoire d&#39;un archer sylvain ; il ne s&#39;en sortira peut-&ecirc;tre pas vivant.<br />\r\nL&#39;archer Sylvain est un personnage patient, attentif, calme et mortellement pr&eacute;cis. C&#39;est un tueur discret qui op&egrave;re de tr&egrave;s loin, et dont les fl&egrave;ches frappent leur cible sans coup f&eacute;rir de bien plus loin que celles des autres archers. Il poss&egrave;de en effet de nombreux pouvoirs magiques qui renforcent la pr&eacute;cision de ses traits.<br />\r\nA cause de leur vigilance, de leur dext&eacute;rit&eacute;, de leur patience et de leur affinit&eacute; avec l&#39;arc, les elfes de presque toutes les classes de personnage font d&#39;excellents archers sylvains. Pendant longtemps, les elfes n&#39;ont entra&icirc;n&eacute; &agrave; ces techniques que les leurs, mais on a r&eacute;cemment vu des demi-elfes, des halfelins et des humains gonfler les rangs de cette classe de prestige.</p>\r\n', cla_traits = NULL, cla_caracteristiques = NULL, cla_critere_rec = NULL, cla_pouvoir1 = NULL, cla_pouvoir2 = NULL, cla_pouvoir3 = NULL, cla_pouvoir4 = NULL, cla_pouvoir5 = NULL, cla_public = 0, cla_visible = 1, cla_ruleset_var_id = 1, cla_res_id = @xc_res_37, cla_cla_id = 0, cla_camp_id = NULL WHERE cla_id = @xc_cla_47;

